/**
 * Amana Vault — CASTLED MODULE 20261015CASTLE
 * ---------------------------------------------------------------------------
 * COMPLIANCE: Amanah (trust) — on-device only. Educational, not a bank product.
 * SECURITY BASELINE (at/above prior build):
 *   - AES-GCM 256 + PBKDF2-SHA-256 · 120000 iterations · random salt/iv
 *   - Passphrase never written to localStorage
 *   - Session unlock only; lock on visibility/pagehide/idle
 *   - Failed-attempt lockout with backoff (banking-style)
 *   - Estate/fiqh UI gated until unlock
 * CASTLE RULE: Do not edit this file in casual sitewide refactors.
 *             Change only via explicit security review + version bump.
 * Clarity does not store or recover the passphrase.
 * ---------------------------------------------------------------------------
 */
(function () {
  "use strict";
  if (window.__CLARITY_AMANA_VAULT_CASTLE_V1__) return;
  window.__CLARITY_AMANA_VAULT_CASTLE_V1__ = true;

  var VAULT_KEY = "clarity_amana_vault_blob_v1";
  var META_KEY = "clarity_amana_vault_meta_v1";
  var ATTEMPT_KEY = "clarity_amana_vault_attempts_v1";
  var CASTLE_VER = "20261015CASTLE";

  var SESSION_UNLOCKED = false;
  var sessionKey = null;
  var idleTimer = null;
  var IDLE_MS = 5 * 60 * 1000;
  var MAX_ATTEMPTS = 5;
  var BASE_LOCKOUT_MS = 30 * 1000;

  function b64(buf) {
    var bytes = new Uint8Array(buf);
    var s = "";
    for (var i = 0; i < bytes.length; i++) s += String.fromCharCode(bytes[i]);
    return btoa(s);
  }
  function fromB64(str) {
    var bin = atob(str);
    var bytes = new Uint8Array(bin.length);
    for (var i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    return bytes.buffer;
  }

  async function deriveKey(pass, salt) {
    var enc = new TextEncoder();
    var base = await crypto.subtle.importKey("raw", enc.encode(pass), "PBKDF2", false, ["deriveKey"]);
    return crypto.subtle.deriveKey(
      { name: "PBKDF2", salt: salt, iterations: 120000, hash: "SHA-256" },
      base,
      { name: "AES-GCM", length: 256 },
      false,
      ["encrypt", "decrypt"]
    );
  }

  async function encryptObj(obj, pass) {
    var salt = crypto.getRandomValues(new Uint8Array(16));
    var iv = crypto.getRandomValues(new Uint8Array(12));
    var key = await deriveKey(pass, salt);
    var plain = new TextEncoder().encode(JSON.stringify(obj));
    var cipher = await crypto.subtle.encrypt({ name: "AES-GCM", iv: iv }, key, plain);
    return {
      clarityAmanaEncrypted: 1,
      version: 1,
      castle: CASTLE_VER,
      alg: "AES-GCM",
      kdf: "PBKDF2-SHA256-120000",
      salt: b64(salt),
      iv: b64(iv),
      ciphertext: b64(cipher)
    };
  }

  async function decryptObj(blob, pass) {
    var salt = fromB64(blob.salt);
    var iv = fromB64(blob.iv);
    var key = await deriveKey(pass, new Uint8Array(salt));
    var plain = await crypto.subtle.decrypt(
      { name: "AES-GCM", iv: new Uint8Array(iv) },
      key,
      fromB64(blob.ciphertext)
    );
    return JSON.parse(new TextDecoder().decode(plain));
  }

  function hasVault() {
    try {
      return !!localStorage.getItem(VAULT_KEY);
    } catch (e) {
      return false;
    }
  }

  function readAttempts() {
    try {
      return JSON.parse(localStorage.getItem(ATTEMPT_KEY) || "{}") || {};
    } catch (e) {
      return {};
    }
  }

  function writeAttempts(o) {
    try {
      localStorage.setItem(ATTEMPT_KEY, JSON.stringify(o));
    } catch (e) {}
  }

  function lockoutRemaining() {
    var a = readAttempts();
    if (!a.lockedUntil) return 0;
    return Math.max(0, a.lockedUntil - Date.now());
  }

  function recordFail() {
    var a = readAttempts();
    a.count = (a.count || 0) + 1;
    a.lastFail = Date.now();
    if (a.count >= MAX_ATTEMPTS) {
      var mult = Math.min(8, Math.pow(2, a.count - MAX_ATTEMPTS));
      a.lockedUntil = Date.now() + BASE_LOCKOUT_MS * mult;
    }
    writeAttempts(a);
    return a;
  }

  function clearAttempts() {
    try {
      localStorage.removeItem(ATTEMPT_KEY);
    } catch (e) {}
  }

  function setStatus(msg) {
    var el = document.getElementById("p5-vault-status");
    if (el) el.textContent = msg || "";
  }

  function clearPassFields() {
    try {
      var p = document.getElementById("p5-vault-pass");
      var p2 = document.getElementById("p5-vault-pass2");
      if (p) {
        p.value = "";
        p.type = "password";
      }
      if (p2) {
        p2.value = "";
        p2.type = "password";
      }
      var tog = document.getElementById("p5-vault-toggle");
      if (tog) tog.textContent = "Show passphrase";
    } catch (e) {}
    sessionKey = null;
  }

  function gateEstate(unlocked) {
    try {
      document.documentElement.setAttribute("data-amana-session", unlocked ? "open" : "locked");
      var host = document.getElementById("amana-fiqh-host");
      if (host) {
        host.hidden = !unlocked;
        host.setAttribute("aria-hidden", unlocked ? "false" : "true");
        host.style.display = unlocked ? "" : "none";
      }
      /* Hide family tree / faraid / wasiyyah cards when locked */
      ["user-family-tree-card", "faraid-card", "wasiyyah-card", "fiqh-workflow-card"].forEach(function (id) {
        var el = document.getElementById(id);
        if (el) {
          el.hidden = !unlocked;
          el.style.display = unlocked ? "" : "none";
        }
      });
    } catch (e) {}
  }

  function resetIdle() {
    if (idleTimer) clearTimeout(idleTimer);
    if (!SESSION_UNLOCKED) return;
    idleTimer = setTimeout(function () {
      lockVault();
      setStatus("Locked · session idle timeout (5 min)");
    }, IDLE_MS);
  }

  function updateUI() {
    var card = document.getElementById("p5-vault-card");
    if (card) {
      card.classList.toggle("is-unlocked", SESSION_UNLOCKED);
      card.classList.toggle("is-locked", !SESSION_UNLOCKED);
    }
    var locked = document.getElementById("p5-vault-locked");
    var open = document.getElementById("p5-vault-open");
    if (locked) {
      locked.hidden = SESSION_UNLOCKED;
      locked.style.display = SESSION_UNLOCKED ? "none" : "block";
      locked.setAttribute("aria-hidden", SESSION_UNLOCKED ? "true" : "false");
    }
    if (open) {
      open.hidden = !SESSION_UNLOCKED;
      open.style.display = SESSION_UNLOCKED ? "block" : "none";
      open.setAttribute("aria-hidden", SESSION_UNLOCKED ? "false" : "true");
    }
    var badge = document.getElementById("p5-vault-badge");
    if (badge) badge.textContent = SESSION_UNLOCKED ? "Vault open · this session only" : "Vault locked";
    var setupBtn = document.getElementById("p5-vault-setup");
    if (setupBtn) setupBtn.style.display = hasVault() || SESSION_UNLOCKED ? "none" : "inline-block";
    var unlockBtn = document.getElementById("p5-vault-unlock");
    if (unlockBtn) {
      unlockBtn.style.display = hasVault() && !SESSION_UNLOCKED ? "inline-block" : "none";
      var wait = lockoutRemaining();
      unlockBtn.disabled = wait > 0;
    }
    var conf = document.getElementById("p5-vault-pass2-wrap");
    if (conf) conf.style.display = hasVault() || SESSION_UNLOCKED ? "none" : "block";
    var mode = document.getElementById("p5-vault-mode");
    if (mode) {
      var wait = lockoutRemaining();
      if (wait > 0) {
        mode.textContent = "Too many failed attempts — try again in " + Math.ceil(wait / 1000) + "s.";
      } else if (SESSION_UNLOCKED) {
        mode.textContent = "Session open — estate tools unlocked. Lock when finished.";
      } else if (hasVault()) {
        mode.textContent = "Vault exists on this device — unlock with your passphrase.";
      } else {
        mode.textContent = "No vault yet — create one with First-time setup (confirm passphrase).";
      }
    }
    gateEstate(SESSION_UNLOCKED);
    if (SESSION_UNLOCKED) resetIdle();
  }

  async function setupVault() {
    if (!window.crypto || !crypto.subtle) {
      setStatus("Web Crypto not available — use a modern browser with HTTPS.");
      return;
    }
    if (lockoutRemaining() > 0) {
      setStatus("Locked out — wait before setup.");
      updateUI();
      return;
    }
    if (hasVault()) {
      if (!confirm("A vault already exists. Creating a new one overwrites the encrypted blob. Continue only if the old passphrase is disposable.")) return;
    }
    var p1 = (document.getElementById("p5-vault-pass") || {}).value || "";
    var p2 = (document.getElementById("p5-vault-pass2") || {}).value || "";
    if (p1.length < 8) {
      setStatus("Use at least 8 characters (longer is safer).");
      return;
    }
    if (p1 !== p2) {
      setStatus("Passphrases did not match — re-enter both fields.");
      return;
    }
    if (!confirm("Confirm: write this passphrase offline (not in this app). If lost, vault data cannot be recovered. Continue?")) {
      setStatus("Setup cancelled.");
      return;
    }
    try {
      var empty = { notes: "", contacts: "", debts: "", wasiyyah: "", updatedAt: new Date().toISOString() };
      var blob = await encryptObj(empty, p1);
      localStorage.setItem(VAULT_KEY, JSON.stringify(blob));
      localStorage.setItem(META_KEY, JSON.stringify({ createdAt: new Date().toISOString(), kdf: "PBKDF2-SHA256-120000", castle: CASTLE_VER }));
      clearAttempts();
      SESSION_UNLOCKED = true;
      window.__AMANA_VAULT_DATA__ = empty;
      clearPassFields();
      setStatus("Vault created · passphrase only in your memory — lock when finished.");
      updateUI();
      renderVaultData(empty);
    } catch (e) {
      setStatus("Setup failed: " + (e && e.message ? e.message : e));
    }
  }

  async function unlockVault() {
    if (!window.crypto || !crypto.subtle) {
      setStatus("Web Crypto not available");
      return;
    }
    var wait = lockoutRemaining();
    if (wait > 0) {
      setStatus("Too many failed attempts — wait " + Math.ceil(wait / 1000) + "s");
      updateUI();
      return;
    }
    var pass = (document.getElementById("p5-vault-pass") || {}).value || "";
    if (!pass) {
      setStatus("Enter passphrase");
      return;
    }
    try {
      var raw = localStorage.getItem(VAULT_KEY);
      if (!raw) {
        setStatus("No vault yet — use First-time setup");
        return;
      }
      var data = await decryptObj(JSON.parse(raw), pass);
      clearAttempts();
      SESSION_UNLOCKED = true;
      window.__AMANA_VAULT_DATA__ = data;
      clearPassFields();
      setStatus("Unlocked for this session — estate tools available. Lock when you leave.");
      updateUI();
      renderVaultData(data);
    } catch (e) {
      var a = recordFail();
      SESSION_UNLOCKED = false;
      window.__AMANA_VAULT_DATA__ = null;
      var left = Math.max(0, MAX_ATTEMPTS - (a.count || 0));
      if (lockoutRemaining() > 0) {
        setStatus("Unlock failed — temporary lockout after failed attempts.");
      } else {
        setStatus("Unlock failed — wrong passphrase or corrupted vault" + (left ? " · " + left + " tries left" : ""));
      }
      updateUI();
    }
  }

  function lockVault() {
    SESSION_UNLOCKED = false;
    window.__AMANA_VAULT_DATA__ = null;
    clearPassFields();
    if (idleTimer) {
      clearTimeout(idleTimer);
      idleTimer = null;
    }
    setStatus("Locked");
    updateUI();
  }

  async function saveVaultFields() {
    if (!SESSION_UNLOCKED) {
      setStatus("Unlock first");
      return;
    }
    var pass = prompt("Re-enter passphrase to save (not stored by Clarity):") || "";
    if (!pass) return;
    var data = {
      notes: (document.getElementById("p5-vault-notes") || {}).value || "",
      contacts: (document.getElementById("p5-vault-contacts") || {}).value || "",
      debts: (document.getElementById("p5-vault-debts") || {}).value || "",
      wasiyyah: (document.getElementById("p5-vault-wasiyyah") || {}).value || "",
      updatedAt: new Date().toISOString()
    };
    try {
      localStorage.setItem(VAULT_KEY, JSON.stringify(await encryptObj(data, pass)));
      window.__AMANA_VAULT_DATA__ = data;
      setStatus("Saved encrypted on this device · " + data.updatedAt);
      resetIdle();
    } catch (e) {
      setStatus("Save failed — check passphrase");
    }
  }

  function renderVaultData(data) {
    if (!data) return;
    try {
      var n = document.getElementById("p5-vault-notes");
      var c = document.getElementById("p5-vault-contacts");
      var d = document.getElementById("p5-vault-debts");
      var w = document.getElementById("p5-vault-wasiyyah");
      if (n) n.value = data.notes || "";
      if (c) c.value = typeof data.contacts === "string" ? data.contacts : JSON.stringify(data.contacts || "");
      if (d) d.value = typeof data.debts === "string" ? data.debts : JSON.stringify(data.debts || "");
      if (w) w.value = data.wasiyyah || "";
    } catch (e) {}
  }

  function mount() {
    if (document.getElementById("p5-vault-card")) {
      updateUI();
      return;
    }
    var card = document.createElement("div");
    card.id = "p5-vault-card";
    card.className = "p5-vault-card is-locked";
    card.setAttribute("data-castle", CASTLE_VER);
    card.innerHTML =
      "<h3>🔒 Amana Vault</h3>" +
      '<div class="p5-vault-warn"><strong>You are responsible for your passphrase.</strong> Clarity does not store it and cannot recover vault data if it is lost. Educational workspace — not a fatwa, not a court document, not legal advice.</div>' +
      '<div class="p5-vault-process"><strong>How to create &amp; safeguard</strong><ol>' +
      "<li><strong>Choose a passphrase</strong> only you know (at least 8 characters).</li>" +
      "<li><strong>Confirm it</strong>, then tap <em>First-time setup</em>.</li>" +
      "<li><strong>Write it offline</strong>. Do not save it in this app.</li>" +
      "<li><strong>Lock</strong> when you leave. Idle and tab-hide also lock.</li>" +
      "<li><strong>Export</strong> sealed package (🕋) before changing devices.</li></ol>" +
      '<p class="p5-vault-tech">AES-GCM · PBKDF2-SHA-256 · 120 000 iterations · attempt lockout · 5 min idle lock · estate gated until unlock. Castle ' +
      CASTLE_VER +
      ".</p></div>" +
      '<div id="p5-vault-badge" class="p5-vault-status">Vault locked</div>' +
      '<p id="p5-vault-mode" class="p5-vault-mode"></p>' +
      '<div id="p5-vault-locked">' +
      '<label>Passphrase</label><br/>' +
      '<input type="password" id="p5-vault-pass" autocomplete="current-password" placeholder="Enter passphrase" />' +
      '<div id="p5-vault-pass2-wrap"><label>Confirm (setup only)</label><br/>' +
      '<input type="password" id="p5-vault-pass2" autocomplete="new-password" placeholder="Confirm passphrase" /></div>' +
      '<button type="button" id="p5-vault-toggle" class="p5-vault-toggle">Show passphrase</button>' +
      '<div class="p5-vault-actions">' +
      '<button type="button" class="primary" id="p5-vault-unlock">Unlock</button>' +
      '<button type="button" id="p5-vault-setup">First-time setup</button></div></div>' +
      '<div id="p5-vault-open" hidden style="display:none">' +
      "<label>Notes</label><textarea id=\"p5-vault-notes\" rows=\"3\"></textarea>" +
      "<label>ICE contacts</label><textarea id=\"p5-vault-contacts\" rows=\"2\"></textarea>" +
      "<label>Debts / rights</label><textarea id=\"p5-vault-debts\" rows=\"2\"></textarea>" +
      "<label>Waṣiyyah notes (≤⅓)</label><textarea id=\"p5-vault-wasiyyah\" rows=\"2\"></textarea>" +
      '<div class="p5-vault-actions">' +
      '<button type="button" class="primary" id="p5-vault-save">Save encrypted</button>' +
      '<button type="button" id="p5-vault-lock">Lock</button></div></div>' +
      '<div class="p5-vault-status" id="p5-vault-status"></div>';

    var host = document.getElementById("amana-vault-host") || document.getElementById("tab-notes") || document.body;
    var disc = host.querySelector && host.querySelector(".amana-disclaimer");
    if (disc && disc.nextSibling) host.insertBefore(card, disc.nextSibling);
    else host.appendChild(card);

    document.getElementById("p5-vault-unlock").onclick = function () {
      unlockVault();
    };
    document.getElementById("p5-vault-setup").onclick = function () {
      setupVault();
    };
    document.getElementById("p5-vault-lock").onclick = function () {
      lockVault();
    };
    document.getElementById("p5-vault-save").onclick = function () {
      saveVaultFields();
    };
    var tog = document.getElementById("p5-vault-toggle");
    if (tog)
      tog.onclick = function () {
        var p = document.getElementById("p5-vault-pass");
        var p2 = document.getElementById("p5-vault-pass2");
        if (!p) return;
        var show = p.type === "password";
        p.type = show ? "text" : "password";
        if (p2) p2.type = p.type;
        tog.textContent = show ? "Hide passphrase" : "Show passphrase";
      };
    ["p5-vault-pass", "p5-vault-pass2", "p5-vault-notes", "p5-vault-contacts", "p5-vault-debts", "p5-vault-wasiyyah"].forEach(function (id) {
      var el = document.getElementById(id);
      if (el) el.addEventListener("input", resetIdle);
    });
    updateUI();
  }

  function boot() {
    mount();
    var api = {
      version: CASTLE_VER,
      hasVault: hasVault,
      unlock: unlockVault,
      lock: lockVault,
      isOpen: function () {
        return SESSION_UNLOCKED;
      }
    };
    try {
      Object.freeze(api);
    } catch (e) {}
    window.ClarityVault = api;
  }

  document.addEventListener("visibilitychange", function () {
    if (document.visibilityState === "hidden") {
      try {
        lockVault();
      } catch (e) {}
    }
  });
  window.addEventListener("pagehide", function () {
    try {
      lockVault();
    } catch (e) {}
  });
  document.addEventListener("click", resetIdle, true);
  document.addEventListener("keydown", resetIdle, true);

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", function () {
      setTimeout(boot, 200);
    });
  } else setTimeout(boot, 200);
})();
